// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("a key's shard is its hash code mod the shard count", () -> {
        eq(shardOf("a", 10), 7);
        eq(shardOf("b", 10), 8);
        eq(shardOf("a", 4), 1);
    });
    test("the same key always lands on the same shard", () ->
        eq(shardOf("user-42", 16), shardOf("user-42", 16)));
    test("a negative hash code still gives a shard in range", () -> {
        eq(shardOf("polygenelubricants", 10), 2);
        eq(shardOf("negative-hash", 10), 6);
    });
    test("refuses fewer than one shard", () -> {
        raises(IllegalArgumentException.class, () -> shardOf("a", 0));
        raises(IllegalArgumentException.class, () -> shardOf("a", -4));
    });
    test("distribute lists every shard, keys in input order", () ->
        eq(distribute(List.of("a", "b", "k", "e"), 4),
           Map.of(0, List.of(), 1, List.of("a", "e"), 2, List.of("b"), 3, List.of("k"))));
    test("one shard holds every key", () ->
        eq(distribute(List.of("x", "y", "z"), 1), Map.of(0, List.of("x", "y", "z"))));
    test("growing from 4 to 5 shards moves most keys", () -> {
        eq(movedKeys(users(1000), 4, 5), 814);
        ok(movedKeys(users(1000), 4, 5) > 700);
    });
    test("doubling from 4 to 8 shards moves about half", () ->
        eq(movedKeys(users(1000), 4, 8), 501));
    test("keeping the shard count moves nothing", () ->
        eq(movedKeys(users(1000), 6, 6), 0));
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("small ids are one digit", () -> {
        eq(encode(0), "0");
        eq(encode(9), "9");
        eq(encode(10), "a");
        eq(encode(36), "A");
        eq(encode(61), "Z");
    });
    test("larger ids carry into more digits", () -> {
        eq(encode(62), "10");
        eq(encode(3843), "ZZ");
        eq(encode(3844), "100");
        eq(encode(Long.MAX_VALUE), "aZl8N0y58M7");
    });
    test("decode reverses encode", () -> {
        for (long id : new long[] {0, 1, 61, 62, 125, 999_999_937L, 3_521_614_606_207L, Long.MAX_VALUE}) {
            eq(decode(encode(id)), id);
        }
    });
    test("decode is case-sensitive and allows leading zeros", () -> {
        eq(decode("a"), 10);
        eq(decode("A"), 36);
        eq(decode("0a"), 10);
        eq(decode("000"), 0);
    });
    test("refuses negative ids", () ->
        raises(IllegalArgumentException.class, () -> encode(-1)));
    test("refuses empty codes and foreign characters", () -> {
        raises(IllegalArgumentException.class, () -> decode(""));
        raises(IllegalArgumentException.class, () -> decode("ab-c"));
        raises(IllegalArgumentException.class, () -> decode("abc def"));
    });
    test("refuses a code too big for a long instead of wrapping", () -> {
        raises(IllegalArgumentException.class, () -> decode("aZl8N0y58M8"));
        raises(IllegalArgumentException.class, () -> decode("zzzzzzzzzzzz"));
        raises(IllegalArgumentException.class, () -> decode("w0000000000"));
    });
    test("capacity is 62 to the power of the length", () -> {
        eq(capacity(1), 62);
        eq(capacity(2), 3844);
        eq(capacity(7), 3_521_614_606_208L);
        eq(capacity(10), 839_299_365_868_340_224L);
    });
    test("capacity refuses lengths that are empty or overflow", () -> {
        raises(IllegalArgumentException.class, () -> capacity(0));
        raises(IllegalArgumentException.class, () -> capacity(11));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

