public static void main(String[] args) {
    test("a key goes to the range that holds it", () -> {
        var r = gp();
        eq(r.count(), 3);
        eq(r.partitionOf("apple"), 0);
        eq(r.partitionOf("kiwi"), 1);
        eq(r.partitionOf("zebra"), 2);
    });
    test("a split point belongs to the partition it starts", () -> {
        var r = gp();
        eq(r.partitionOf("g"), 1);
        eq(r.partitionOf("p"), 2);
        eq(r.partitionOf("fzzz"), 0);
        eq(r.partitionOf(""), 0);
    });
    test("refuses split points that are not strictly ascending", () -> {
        raises(IllegalArgumentException.class, () -> new RangePartitioner(List.of("p", "g")));
        raises(IllegalArgumentException.class, () -> new RangePartitioner(List.of("g", "g")));
        eq(new RangePartitioner(List.of()).partitionOf("anything"), 0);
    });
    test("a range scan touches only the partitions it overlaps", () -> {
        var r = gp();
        eq(r.partitionsFor("h", "k"), List.of(1));
        eq(r.partitionsFor("f", "h"), List.of(0, 1));
        eq(r.partitionsFor("a", "z"), List.of(0, 1, 2));
    });
    test("the end of a scan is exclusive", () -> {
        var r = gp();
        eq(r.partitionsFor("a", "g"), List.of(0));
        eq(r.partitionsFor("g", "p"), List.of(1));
        eq(r.partitionsFor("a", "gg"), List.of(0, 1));
        eq(r.partitionsFor("k", "k"), List.of());
    });
    test("refuses a backwards scan", () ->
        raises(IllegalArgumentException.class, () -> gp().partitionsFor("z", "a")));
    test("splitting a hot partition", () -> {
        var r = gp();
        r.split("m");
        eq(r.count(), 4);
        eq(r.splitPoints(), List.of("g", "m", "p"));
        eq(r.partitionOf("kiwi"), 1);
        eq(r.partitionOf("mango"), 2);
        eq(r.partitionOf("zebra"), 3);
        raises(IllegalArgumentException.class, () -> r.split("g"));
    });
    test("keeps its own copy and exposes it read-only", () -> {
        var input = new ArrayList<>(List.of("g", "p"));
        var r = new RangePartitioner(input);
        input.add("z");
        eq(r.splitPoints(), List.of("g", "p"));
        raises(UnsupportedOperationException.class, () -> r.splitPoints().add("x"));
    });
    test("even splits from a sorted sample", () -> {
        var sample = List.of("a", "b", "c", "d", "e", "f", "g", "h");
        eq(evenSplits(sample, 4), List.of("c", "e", "g"));
        eq(evenSplits(sample, 3), List.of("c", "f"));
        eq(evenSplits(sample, 1), List.of());
        raises(IllegalArgumentException.class, () -> evenSplits(sample, 0));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("a key belongs to the first point clockwise", () -> {
        var r = toyRing(1, "A", "B", "C");
        eq(r.nodeFor("k50"), "A");
        eq(r.nodeFor("k150"), "B");
        eq(r.nodeFor("k220"), "C");
    });
    test("a key exactly on a point belongs to that point", () ->
        eq(toyRing(1, "A", "B", "C").nodeFor("k200"), "B"));
    test("keys past the last point wrap to the first", () ->
        eq(toyRing(1, "A", "B", "C").nodeFor("k301"), "A"));
    test("virtual nodes give a node several points", () -> {
        var r = toyRing(2, "A", "B");
        eq(r.nodeFor("k50"), "B");
        eq(r.nodeFor("k150"), "B");
        eq(r.nodeFor("k220"), "A");
        eq(r.nodeFor("k301"), "B");
        eq(r.nodes(), List.of("A", "B"));
    });
    test("removing a node hands its keys to the next point only", () -> {
        var r = toyRing(1, "A", "B", "C");
        r.removeNode("B");
        eq(r.nodeFor("k150"), "C");
        eq(r.nodeFor("k200"), "C");
        eq(r.nodeFor("k50"), "A");
        eq(r.nodes(), List.of("A", "C"));
    });
    test("refuses bad vnode counts, duplicate and unknown nodes", () -> {
        raises(IllegalArgumentException.class, () -> new Ring(0, Exercise::hash64));
        var r = toyRing(1, "A");
        raises(IllegalArgumentException.class, () -> r.addNode("A"));
        raises(IllegalArgumentException.class, () -> r.removeNode("Z"));
    });
    test("an empty ring refuses lookups", () -> {
        var r = new Ring(8, Exercise::hash64);
        raises(IllegalStateException.class, () -> r.nodeFor("x"));
        r.addNode("solo");
        eq(r.nodeFor("x"), "solo");
        r.removeNode("solo");
        raises(IllegalStateException.class, () -> r.nodeFor("x"));
    });
    test("adding a node moves keys only onto the new node", () -> {
        var r = new Ring(100, Exercise::hash64);
        for (var n : List.of("A", "B", "C")) r.addNode(n);
        var before = new HashMap<String, String>();
        for (var k : keys(2000)) before.put(k, r.nodeFor(k));
        r.addNode("D");
        int moved = 0;
        for (var k : keys(2000)) {
            if (!r.nodeFor(k).equals(before.get(k))) {
                eq(r.nodeFor(k), "D");
                moved++;
            }
        }
        ok(moved > 300 && moved < 700, "about a quarter of 2000 keys should move, moved " + moved);
    });
    test("many virtual nodes spread keys evenly", () -> {
        var r = new Ring(200, Exercise::hash64);
        for (var n : List.of("D", "B", "A", "C")) r.addNode(n);
        eq(r.nodes(), List.of("A", "B", "C", "D"));
        var load = new TreeMap<String, Integer>();
        for (var k : keys(4000)) load.merge(r.nodeFor(k), 1, Integer::sum);
        eq(load.keySet(), Set.of("A", "B", "C", "D"));
        for (int n : load.values()) ok(n > 700 && n < 1300, "uneven load " + load);
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("the node with the highest score owns the key", () -> {
        eq(owner("k", List.of("A", "B", "C"), toy()), "B");
        eq(owner("m", List.of("A", "B", "C"), toy()), "B");
    });
    test("a tied score goes to the alphabetically smaller name", () -> {
        eq(owner("t", List.of("B", "A", "C"), toy()), "A");
        eq(replicas("t", List.of("B", "C", "A"), 3, toy()), List.of("A", "B", "C"));
    });
    test("the order of the node list does not matter", () -> {
        eq(owner("k", List.of("C", "B", "A"), toy()), "B");
        eq(owner("k", List.of("B", "C", "A"), toy()), "B");
    });
    test("replicas are the best-scoring nodes, best first", () -> {
        eq(replicas("k", List.of("C", "A", "B"), 2, toy()), List.of("B", "C"));
        eq(replicas("k", List.of("A", "B", "C"), 1, toy()), List.of("B"));
        eq(replicas("m", List.of("A", "B", "C"), 3, toy()), List.of("B", "C", "A"));
    });
    test("asking for more replicas than nodes returns them all", () ->
        eq(replicas("k", List.of("A", "B", "C"), 9, toy()), List.of("B", "C", "A")));
    test("refuses an empty node list and n < 1", () -> {
        raises(IllegalArgumentException.class, () -> owner("k", List.of(), toy()));
        raises(IllegalArgumentException.class, () -> replicas("k", List.of(), 2, toy()));
        raises(IllegalArgumentException.class, () -> replicas("k", List.of("A"), 0, toy()));
    });
    test("removing a node only moves the keys it owned", () -> {
        var all = List.of("n1", "n2", "n3", "n4", "n5");
        var fewer = List.of("n1", "n2", "n4", "n5");
        int moved = 0;
        for (var k : keys(2000)) {
            var before = owner(k, all, Exercise::hash64);
            var after = owner(k, fewer, Exercise::hash64);
            if (!before.equals(after)) {
                eq(before, "n3");
                eq(after, replicas(k, all, 2, Exercise::hash64).get(1));
                moved++;
            }
        }
        ok(moved > 250 && moved < 550, "about a fifth of 2000 keys should move, moved " + moved);
    });
    test("adding a node only steals keys for itself", () -> {
        var old = List.of("n1", "n2", "n3");
        var grown = List.of("n1", "n2", "n3", "n4");
        for (var k : keys(2000)) {
            var after = owner(k, grown, Exercise::hash64);
            if (!after.equals(owner(k, old, Exercise::hash64))) eq(after, "n4");
        }
    });
    test("spreads keys roughly evenly", () -> {
        var load = new TreeMap<String, Integer>();
        for (var k : keys(3000)) load.merge(owner(k, List.of("x", "y", "z"), Exercise::hash64), 1, Integer::sum);
        eq(load.keySet(), Set.of("x", "y", "z"));
        for (int n : load.values()) ok(n > 800 && n < 1200, "uneven load " + load);
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("packs time, worker and sequence into one long", () -> {
        var g = new Snowflake(0, 7, script(5));
        eq(g.next(), (5L << 22) | (7L << 12));
        eq(new Snowflake(1_000, 1, script(1_003)).next(), (3L << 22) | (1L << 12));
    });
    test("ids in the same millisecond count up the sequence", () -> {
        var g = new Snowflake(0, 7, script(5));
        g.next();
        eq(g.next() & 0xFFF, 1);
        eq(g.next() & 0xFFF, 2);
    });
    test("a new millisecond resets the sequence to zero", () -> {
        var g = new Snowflake(0, 7, script(5, 5, 5, 6));
        g.next();
        g.next();
        g.next();
        eq(Snowflake.parse(g.next(), 0), new Parts(6, 7, 0));
    });
    test("parse takes an id apart", () -> {
        var epoch = 1_288_834_974_657L;
        var g = new Snowflake(epoch, 1023, script(epoch + 86_400_000L));
        g.next();
        eq(Snowflake.parse(g.next(), epoch), new Parts(epoch + 86_400_000L, 1023, 1));
    });
    test("ids keep increasing as time moves on", () -> {
        var g = new Snowflake(0, 3, script(10, 10, 11, 15, 15, 15, 40));
        long previous = -1;
        for (int i = 0; i < 7; i++) {
            long id = g.next();
            ok(id > previous, "id " + i + " did not increase");
            previous = id;
        }
    });
    test("a used-up millisecond waits for the clock to move on", () -> {
        var reads = new int[1];
        var g = new Snowflake(0, 2, () -> reads[0]++ < 4100 ? 1_000L : 1_001L);
        long previous = -1;
        for (int i = 0; i < 4096; i++) {
            long id = g.next();
            ok(id > previous, "id " + i + " did not increase");
            previous = id;
        }
        eq(Snowflake.parse(previous, 0), new Parts(1_000, 2, 4095));
        long overflow = g.next();
        eq(Snowflake.parse(overflow, 0), new Parts(1_001, 2, 0));
        eq(reads[0], 4101);
    });
    test("refuses a clock that moved backwards", () -> {
        var g = new Snowflake(0, 1, script(50, 49));
        g.next();
        raises(IllegalStateException.class, g::next);
    });
    test("refuses a worker id outside 0..1023", () -> {
        raises(IllegalArgumentException.class, () -> new Snowflake(0, -1, script(1)));
        raises(IllegalArgumentException.class, () -> new Snowflake(0, 1024, script(1)));
        eq(Snowflake.parse(new Snowflake(0, 1023, script(1)).next(), 0), new Parts(1, 1023, 0));
    });
    test("two workers never collide in the same millisecond", () -> {
        var a = new Snowflake(0, 1, script(9));
        var b = new Snowflake(0, 2, script(9));
        var seen = new HashSet<Long>();
        for (int i = 0; i < 100; i++) {
            ok(seen.add(a.next()));
            ok(seen.add(b.next()));
        }
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("an empty filter contains nothing", () -> {
        var f = new Bloom(1000, 4);
        eq(f.mightContain("apple"), false);
        eq(f.bitsSet(), 0);
    });
    test("positions are double-hashed indexes", () -> {
        eq(new Bloom(1000, 4).positions("apple"), new int[] {449, 574, 995, 120});
        eq(new Bloom(97, 3).positions("user-1"), new int[] {11, 54, 62});
    });
    test("an added key is always reported", () -> {
        var f = new Bloom(10_000, 7);
        for (int i = 0; i < 1000; i++) f.add("user-" + i);
        for (int i = 0; i < 1000; i++) ok(f.mightContain("user-" + i), "lost user-" + i);
    });
    test("adding sets the key's bits once", () -> {
        var f = new Bloom(1000, 4);
        f.add("apple");
        var distinct = new HashSet<Integer>();
        for (int p : f.positions("apple")) distinct.add(p);
        eq(f.bitsSet(), distinct.size());
        f.add("apple");
        eq(f.bitsSet(), distinct.size());
    });
    test("a key with any bit unset is definitely absent", () -> {
        var f = new Bloom(1000, 4);
        f.add("apple");
        eq(f.mightContain("apple"), true);
        eq(f.mightContain("banana"), false);
        eq(f.mightContain("Apple"), false);
    });
    test("the measured false-positive rate is near the formula", () -> {
        var f = new Bloom(10_000, 7);
        for (int i = 0; i < 1000; i++) f.add("user-" + i);
        int fp = 0;
        for (int i = 0; i < 10_000; i++) if (f.mightContain("ghost-" + i)) fp++;
        eq(fp, 85);
        ok(fp > 20 && fp < 200, "false positives: " + fp);
    });
    test("the optimal hash count is bits per item times ln 2", () -> {
        eq(optimalHashes(10_000, 1_000), 7);
        eq(optimalHashes(10_000, 1_500), 5);
        eq(optimalHashes(100, 1_000), 1);
        raises(IllegalArgumentException.class, () -> optimalHashes(100, 0));
    });
    test("the false-positive formula", () -> {
        approx(falsePositiveRate(10_000, 7, 1_000), 0.008193, 1e-5);
        approx(falsePositiveRate(1_000, 1, 1_000), 1 - Math.exp(-1), 1e-12);
        approx(falsePositiveRate(1_000, 4, 0), 0.0, 1e-12);
    });
    test("refuses empty sizes", () -> {
        raises(IllegalArgumentException.class, () -> new Bloom(0, 3));
        raises(IllegalArgumentException.class, () -> new Bloom(100, 0));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("R + W > N is the overlap rule", () -> {
        eq(Cluster.isStrong(3, 2, 2), true);
        eq(Cluster.isStrong(3, 1, 2), false);
        eq(Cluster.isStrong(3, 1, 3), true);
        eq(Cluster.isStrong(5, 2, 3), false);
        eq(Cluster.isStrong(5, 3, 3), true);
    });
    test("refuses quorums outside 1..N and unknown replicas", () -> {
        raises(IllegalArgumentException.class, () -> new Cluster(3, 0, 2));
        raises(IllegalArgumentException.class, () -> new Cluster(3, 2, 4));
        var c = new Cluster(3, 1, 1);
        raises(IllegalArgumentException.class, () -> c.write("x", "a", Set.of(3)));
        raises(IllegalArgumentException.class, () -> c.read("x", Set.of(-1)));
    });
    test("a write lands on every reachable replica", () -> {
        var c = new Cluster(3, 2, 2);
        eq(c.write("x", "a", Set.of(0, 1, 2)), 1);
        for (int i = 0; i < 3; i++) eq(c.stored(i, "x"), Optional.of(new Versioned("a", 1)));
        eq(c.write("y", "b", Set.of(0, 2)), 2);
        eq(c.stored(1, "y"), Optional.empty());
    });
    test("a write that cannot reach W replicas stores nothing", () -> {
        var c = new Cluster(3, 2, 2);
        raises(IllegalStateException.class, () -> c.write("x", "a", Set.of(2)));
        eq(c.stored(2, "x"), Optional.empty());
        eq(c.write("x", "b", Set.of(0, 1)), 1);
    });
    test("with R + W > N every read sees the latest write", () -> {
        var c = new Cluster(3, 2, 2);
        c.write("x", "a", Set.of(0, 1, 2));
        c.write("x", "b", Set.of(0, 1));
        eq(c.read("x", Set.of(1, 2)), Optional.of("b"));
        eq(c.read("x", Set.of(0, 2)), Optional.of("b"));
    });
    test("with R + W <= N a read can be stale", () -> {
        var c = new Cluster(3, 1, 1);
        c.write("x", "a", Set.of(0, 1, 2));
        c.write("x", "b", Set.of(0));
        eq(c.read("x", Set.of(1, 2)), Optional.of("a"));
        eq(c.read("x", Set.of(0, 1, 2)), Optional.of("b"));
    });
    test("the highest version wins, not the lowest replica", () -> {
        var c = new Cluster(3, 3, 1);
        c.write("x", "a", Set.of(0, 1, 2));
        c.write("x", "b", Set.of(2));
        eq(c.read("x", Set.of(0, 1, 2)), Optional.of("b"));
    });
    test("read repair fixes only the replicas it contacted", () -> {
        var c = new Cluster(4, 2, 2);
        c.write("x", "a", Set.of(0, 1));
        eq(c.read("x", Set.of(1, 2, 3)), Optional.of("a"));
        eq(c.stored(2, "x"), Optional.of(new Versioned("a", 1)));
        eq(c.stored(3, "x"), Optional.empty());
        c.write("x", "b", Set.of(2, 3));
        eq(c.read("x", Set.of(0, 2)), Optional.of("b"));
        eq(c.stored(0, "x"), Optional.of(new Versioned("b", 2)));
        eq(c.stored(1, "x"), Optional.of(new Versioned("a", 1)));
    });
    test("a read needs R replicas and may find nothing", () -> {
        var c = new Cluster(3, 2, 2);
        raises(IllegalStateException.class, () -> c.read("x", Set.of(1)));
        eq(c.read("missing", Set.of(0, 1)), Optional.empty());
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

